@page "/chat"
@rendermode InteractiveServer
@inject IChatService ChatService

<PageTitle>Chat</PageTitle>

<div class="chat-layout">
    <div class="chat-sidebar">
        <ChannelList Channels="channels"
                     SelectedChannelId="selectedChannelId"
                     OnChannelSelected="SelectChannel" />
    </div>

    <div class="chat-main @(isThreadOpen ? "with-thread" : "")">
        @if (selectedChannel is not null)
        {
            <MessageArea ChannelName="@selectedChannel.Name"
                         ChannelDescription="@selectedChannel.Description"
                         ChannelId="selectedChannelId"
                         Messages="messages"
                         ThreadSummaries="threadSummaries"
                         OnOpenThread="OpenThread"
                         OnLoadMore="LoadMoreMessages"
                         OnMessageSent="SendMessage" />
        }
    </div>

    @if (isThreadOpen)
    {
        <div class="chat-thread">
            <ThreadPanel RootMessage="threadRootMessage"
                         ThreadMessages="threadMessages"
                         OnClose="CloseThread"
                         OnReplySent="SendThreadReply" />
        </div>
    }
</div>

@code {
    private List<Channel> channels = new();
    private List<Message> messages = new();
    private List<ThreadSummary> threadSummaries = new();
    private List<Message> threadMessages = new();
    private Message? threadRootMessage;

    private int selectedChannelId;
    private Channel? selectedChannel;
    private bool isThreadOpen;
    private int currentThreadRootId;

    private const int PageSize = 30;
    private int currentSkip;

    protected override async Task OnInitializedAsync()
    {
        channels = await ChatService.GetChannelsAsync();
        if (channels.Count > 0)
        {
            await SelectChannel(channels[0].Id);
        }
    }

    private async Task SelectChannel(int channelId)
    {
        selectedChannelId = channelId;
        selectedChannel = channels.FirstOrDefault(c => c.Id == channelId);
        currentSkip = 0;
        messages = await ChatService.GetMessagesAsync(channelId, 0, PageSize);
        currentSkip = messages.Count;
        threadSummaries = GetThreadSummaries(messages);
        await ChatService.MarkChannelReadAsync(channelId);

        // Refresh channel list to update unread counts
        channels = await ChatService.GetChannelsAsync();
    }

    private async Task LoadMoreMessages()
    {
        var older = await ChatService.GetMessagesAsync(selectedChannelId, currentSkip, PageSize);
        if (older.Count > 0)
        {
            messages.InsertRange(0, older);
            currentSkip += older.Count;
            threadSummaries = GetThreadSummaries(messages);
        }
    }

    private async Task SendMessage(string content)
    {
        var message = await ChatService.SendMessageAsync(selectedChannelId, content, null);
        messages.Add(message);
    }

    private async Task OpenThread(int rootMessageId)
    {
        currentThreadRootId = rootMessageId;
        threadRootMessage = messages.FirstOrDefault(m => m.Id == rootMessageId);
        threadMessages = await ChatService.GetThreadAsync(rootMessageId);
        isThreadOpen = true;
    }

    private void CloseThread()
    {
        isThreadOpen = false;
        threadMessages = new();
        threadRootMessage = null;
    }

    private async Task SendThreadReply(string content)
    {
        var reply = await ChatService.SendMessageAsync(selectedChannelId, content, currentThreadRootId);
        threadMessages.Add(reply);
        threadSummaries = GetThreadSummaries(messages);
    }

    private static List<ThreadSummary> GetThreadSummaries(List<Message> msgs)
    {
        // Build thread summaries from messages that have replies
        var rootIds = msgs.Where(m => m.ReplyToId.HasValue)
                         .GroupBy(m => m.ReplyToId!.Value)
                         .Select(g => new ThreadSummary(
                             g.Key,
                             g.Count(),
                             g.Max(m => m.SentAt)))
                         .ToList();
        return rootIds;
    }
}

.chat-layout {
