    font-size: 0.85rem;
}

::deep .thread-root-message p {
    margin: 0.25rem 0 0;
}

::deep .thread-replies {
    flex: 1;
    overflow-y: auto;
    padding: 0.75rem 1rem;
}

::deep .thread-reply {
    padding: 0.4rem 0;
    margin-bottom: 0.35rem;
}
