+    border-radius: 6px;
+    padding: 0.5rem 0.75rem;
+    font-size: 0.9rem;
+    font-family: inherit;
+}
+
+::deep .message-input-area textarea:focus,
+::deep .thread-input-area textarea:focus {
+    outline: none;
+    border-color: #2563eb;
+}
+
+::deep .send-btn {
+    padding: 0.5rem 1rem;
+    background: #2563eb;
+    color: white;
+    border: none;
+    border-radius: 6px;
+    cursor: pointer;
+    font-weight: 500;
+}
+
+::deep .send-btn:hover:not(:disabled) {
+    background: #1d4ed8;
+}
+
+::deep .send-btn:disabled {
+    opacity: 0.5;
+    cursor: not-allowed;
+}
+
+/* Thread Panel */
+::deep .thread-panel {
+    display: flex;
+    flex-direction: column;
+    height: 100%;
+}
+
+::deep .thread-header {
+    display: flex;
+    justify-content: space-between;
+    align-items: center;
+    padding: 0.75rem 1rem;
+    border-bottom: 1px solid #e0e0e0;
+}
+
+::deep .thread-header h3 {
+    margin: 0;
+    font-size: 1rem;
+}
+
+::deep .close-btn {
+    background: none;
+    border: none;
+    font-size: 1.2rem;
+    cursor: pointer;
+    padding: 0.25rem 0.5rem;
+    border-radius: 4px;
+    color: #666;
+}
+
+::deep .close-btn:hover {
+    background: #e0e0e0;
+}
+
+::deep .thread-root-message {
+    padding: 0.75rem 1rem;
+    background: #f0f4ff;
+    border-bottom: 1px solid #e0e0e0;
+    font-size: 0.85rem;
+}
+
+::deep .thread-root-message p {
+    margin: 0.25rem 0 0;
+}
+
+::deep .thread-replies {
+    flex: 1;
+    overflow-y: auto;
+    padding: 0.75rem 1rem;
+}
+
+::deep .thread-reply {
+    padding: 0.4rem 0;
+    margin-bottom: 0.35rem;
+}
+

